        var permit=new CompanyWorkOrderExecutionPermitApprovalReview(stage.Context,proposal,issued,current,ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(recorded)),utc,CompanyWorkOrderExecutionPermitApprovalReview.GetBlockers(proposal,issued,current,utc,1)){PrerequisiteEvidenceVersion=1};var reference=new CompanyWorkOrderExecutionPermitReference(task,proposal.IntentId);var query=template.Source.Query with{Permit=reference};var catalog=template.Source.Catalog with{Context=stage.Context,Permit=reference};var source=template.Source with{Query=query,Catalog=catalog,Revision=""};source=source with{Revision=CompanyWorkOrderPermitDocumentFacts.Digest(source)};var review=new CompanyWorkOrderPermitDocumentReview(permit,source,CompanyWorkOrderPermitDocumentReview.GetBlockers(proposal,source));var command=new CompanyWorkOrderDocumentAcceptanceCommand(review,pending.INSPECTION_ID,Guid.NewGuid(),"Original requirement content verification",true,true){ContributorReview=CompanyPersonnelIdentityClientTests.Contributors("current",review)};command.RequireCurrentAcceptance();var saved=command.Prepare(pending,DateTime.UtcNow);command.RequireRecorded(saved);var observedRows=rows.Select(row=>row.InspectionId==saved.INSPECTION_ID?InspectionRules.ProjectWithRequirementProof(saved):row).ToArray();var observed=current with{Inspections=observedRows,SnapshotRevision=CompanyMaintenanceInspectionReview.Revision(stage,current.InspectionDatabase,current.Order,observedRows)};command.RequireCurrentCore(observed,saved);Assert.Equal(issued.RequirementFactsRevision(),observed.RequirementFactsRevision());var proof=saved.DOCUMENT_ACCEPTANCE_DATA_JSON;
        var facts=command.Facts(saved);utc=DateTime.UtcNow;permit=permit with{CurrentSource=observed,ComparedAtUtc=utc,Blockers=CompanyWorkOrderExecutionPermitApprovalReview.GetBlockers(proposal,issued,observed,utc,1)};var evidence=review with{PermitReview=permit};var contributors=command.ContributorReview!;var comparison=new CompanyWorkOrderAcceptedDocumentReview(facts,evidence,utc,CompanyWorkOrderAcceptedDocumentReview.GetBlockers(proposal,facts,evidence,utc,1,contributors.Contributors,contributors.Identities,contributors.ReviewerPerson)){ContributorComparisonVersion=1,CurrentContributors=contributors.Contributors,CurrentIdentities=contributors.Identities,RecordedReviewerPerson=contributors.ReviewerPerson};comparison.Require(proposal,observed);Assert.Empty(comparison.Blockers);var blockers=CompanyWorkOrderExecutionPermitApprovalReview.GetBlockers(proposal,issued,observed,utc,6,null,null,[comparison]);Assert.DoesNotContain(blockers,value=>value.Contains("facts changed"));Assert.Contains(blockers,value=>value.Contains("RISK document acceptance"));Assert.Contains(blockers,value=>value.Contains("material acceptance"));Assert.Equal(proof,saved.DOCUMENT_ACCEPTANCE_DATA_JSON);command.RequireRecorded(saved);
    }
    [Theory][InlineData("current")][InlineData("content-unread")][InlineData("requirement-unverified")][InlineData("reason")][InlineData("requirement-author")][InlineData("document-author")][InlineData("requirement")][InlineData("changed-audit")][InlineData("digest")]
    public void CanonicalDocumentAcceptanceRequiresExplicitIndependentReviewAndPreservesCompleteNativeAudit(string mode)
    {
        var f=Acceptance();var command=mode switch{"content-unread"=>f.Command with{ContentReviewed=false},"requirement-unverified"=>f.Command with{RequirementVerified=false},"reason"=>f.Command with{Reason=""},"requirement"=>f.Command with{InspectionId="other"},_=>f.Command};
        if(mode=="document-author"){var source=command.Review.Source with{Document=command.Review.Source.Document! with{RecordedBy=command.Review.PermitReview.Context.ActorUserId},Revision=""};source=source with{Revision=CompanyWorkOrderPermitDocumentFacts.Digest(source)};command=command with{Review=command.Review with{Source=source}};}
        if(mode=="requirement-author"){var source=command.Review.PermitReview.CurrentSource;var rows=source.Inspections.Select(row=>row.InspectionId==command.InspectionId?row with{RequirementActor=command.Review.PermitReview.Context.ActorUserId}:row).ToArray();source=source with{Inspections=rows,SnapshotRevision=CompanyMaintenanceInspectionReview.Revision(source.Stage,source.InspectionDatabase,source.Order,rows)};var permit=command.Review.PermitReview;permit=permit with{CurrentSource=source,Blockers=CompanyWorkOrderExecutionPermitApprovalReview.GetBlockers(permit.Proposal,permit.OriginalSource,source,permit.ComparedAtUtc,permit.PrerequisiteEvidenceVersion,permit.CurrentMaterialAcceptance,permit.CurrentPersonnelAcceptance)};command=command with{Review=command.Review with{PermitReview=permit}};}
        var error=Record.Exception(()=>{command.Require();var recorded=command.Prepare(f.Pending,DateTime.UtcNow);if(mode=="changed-audit"){recorded.ROW_CREATED_BY="changed";recorded.DOCUMENT_ACCEPTANCE_REVISION=CompanyWorkOrderDocumentAcceptanceCommand.Digest(recorded);}if(mode=="digest")recorded.DOCUMENT_ACCEPTANCE_REVISION=new string('0',64);command.RequireRecorded(recorded);Assert.Equal(f.Pending.ROW_CREATED_BY,recorded.ROW_CREATED_BY);Assert.DoesNotContain(command.Reason,JsonSerializer.Serialize(InspectionRules.Project(recorded)));Assert.DoesNotContain("\"Bytes\":",recorded.DOCUMENT_ACCEPTANCE_DATA_JSON!);});
        if(mode=="current")Assert.Null(error);else Assert.NotNull(error);
    }
    [Theory][InlineData("record")][InlineData("lost")][InlineData("retain")][InlineData("late")][InlineData("authority")]
    public async Task DocumentDecisionStateRetainsBeforeTransportBlocksReplacementAndRecoversOriginalReference(string mode)
    {
        var f=Acceptance();var context=f.Command.Review.PermitReview.Context;using var company=new CompanyClientContext();Assert.True(company.TrySelect(company.Clear(),context.ActorUserId,new(context.Company,["ConfiguredRole"],mode=="authority"?[]:["HSE.ApprovePermit"])));using var state=new WorkOrderExecutionPermitDecisionState(company);state.Attach(f.Command.Review.Source.Query.Permit,"source");var client=new Mock<ICompanyMaintenanceHandoffClient>();var writes=0;var retained=false;CompanyWorkOrderDocumentAcceptanceCommand? original=null;InspectionRow? saved=null;
        client.Setup(value=>value.RecordWorkOrderDocumentAcceptanceAsync(It.IsAny<CompanyWorkOrderDocumentAcceptanceCommand>(),It.IsAny<CancellationToken>())).Returns((CompanyWorkOrderDocumentAcceptanceCommand command,CancellationToken _)=>{Assert.True(retained);writes++;original=command;saved=command.Prepare(f.Pending,DateTime.UtcNow);if(mode=="late")company.Clear();if(mode=="lost")throw new HttpRequestException("Lost response");return Task.FromResult(saved);});
        var error=await Record.ExceptionAsync(()=>state.AcceptDocumentAsync(client.Object,f.Command.Review,f.Pending.INSPECTION_ID,f.Command.Reason,true,true,command=>{original=command;retained=true;if(mode=="retain")throw new IOException("Retention failed");return Task.CompletedTask;},f.Command.ContributorReview));
        if(mode=="record")Assert.Null(error);else if(mode!="late")Assert.NotNull(error);Assert.Equal(mode is "retain" or "authority"?0:1,writes);if(mode=="authority"){Assert.Null(state.VisibleDocumentAcceptanceReference);return;}
        await Assert.ThrowsAsync<InvalidOperationException>(()=>state.AcceptDocumentAsync(client.Object,f.Command.Review,f.Pending.INSPECTION_ID,"replacement",true,true,_=>Task.CompletedTask,f.Command.ContributorReview));
        if(mode=="lost"){Assert.Throws<InvalidOperationException>(()=>state.BeginNextDocumentAcceptance());var reference=state.VisibleDocumentAcceptanceReference!;client.Setup(value=>value.RecoverWorkOrderDocumentAcceptanceReferenceAsync(reference,It.IsAny<CancellationToken>())).ReturnsAsync(new CompanyWorkOrderDocumentAcceptanceRecovery(original!,saved!));await state.RecoverDocumentAcceptanceReferenceAsync(client.Object,reference);original!.RequireRecorded(state.DocumentAcceptanceReceipt!);Assert.Equal(1,writes);}if(mode=="late")Assert.Null(state.DocumentAcceptanceReceipt);if(mode is "record" or "lost"){state.BeginNextDocumentAcceptance();Assert.True(state.CanAcceptDocument);Assert.Null(state.VisibleDocumentAcceptanceReference);}
    }
