        var source=f.Command.Review.Source with{Catalog=f.Command.Review.Source.Catalog with{Context=context},InformationItem=f.Command.Review.Source.InformationItem! with{Version=mode=="version"?"3":f.Command.Review.Source.InformationItem.Version,AccessCondition=mode=="restricted"?"UNMAPPED RESTRICTION":null},File=f.Command.Review.Source.File! with{ContentRevision=mode=="content"?new string('A',64):f.Command.Review.Source.File.ContentRevision},Revision=""};source=source with{Revision=CompanyWorkOrderPermitDocumentFacts.Digest(source)};
        var evidence=new CompanyWorkOrderPermitDocumentReview(permit,source,CompanyWorkOrderPermitDocumentReview.GetBlockers(permit.Proposal,source));utc=DateTime.UtcNow;var blockers=CompanyWorkOrderAcceptedDocumentReview.GetBlockers(permit.Proposal,accepted,evidence,utc);var comparison=new CompanyWorkOrderAcceptedDocumentReview(accepted,evidence,utc,mode=="forged"?["forged"]:blockers);
        var error=Record.Exception(()=>comparison.Require(permit.Proposal,current));if(mode=="forged")Assert.NotNull(error);else{Assert.Null(error);if(mode is "current" or "different-reviewer")Assert.Empty(comparison.Blockers);else Assert.NotEmpty(comparison.Blockers);}
