        var currentReview=permit with{ComparedAtUtc=DateTime.UtcNow,PrerequisiteEvidenceVersion=4,CurrentMaterialAcceptance=null,CurrentPersonnelAcceptance=null,CurrentDocumentAcceptance=[comparison]};if(mode!="forged"){currentReview=currentReview with{Blockers=CompanyWorkOrderExecutionPermitApprovalReview.GetBlockers(permit.Proposal,permit.OriginalSource,current,currentReview.ComparedAtUtc,4,null,null,[comparison])};currentReview.Require(context.Company,context.ActorUserId,source.Query.Permit);Assert.Contains(currentReview.Blockers,row=>row.Contains("RISK document acceptance"));Assert.Contains(currentReview.Blockers,row=>row.Contains("contributor/reviewer identity mapping"));}
