    [Theory][InlineData("current")][InlineData("creation-audit")]
    public void VersionedDocumentAcceptanceRetainsOriginalImmutableRequirementProof(string mode)
    {
        var f=Acceptance();var original=f.Command.Review.PermitReview;var rows=original.CurrentSource.Inspections.Select(row=>row.InspectionId==f.Pending.INSPECTION_ID?InspectionRules.ProjectWithRequirementProof(f.Pending):row).ToArray();var source=original.CurrentSource with{Inspections=rows,SnapshotRevision=CompanyMaintenanceInspectionReview.Revision(original.CurrentSource.Stage,original.CurrentSource.InspectionDatabase,original.CurrentSource.Order,rows)};var permit=original with{CurrentSource=source,Blockers=CompanyWorkOrderExecutionPermitApprovalReview.GetBlockers(original.Proposal,original.OriginalSource,source,original.ComparedAtUtc,original.PrerequisiteEvidenceVersion)};var review=f.Command.Review with{PermitReview=permit};var contributors=f.Command.ContributorReview! with{Document=review};var command=f.Command with{Review=review,ContributorReview=contributors};command.RequireCurrentAcceptance();var saved=command.Prepare(f.Pending,DateTime.UtcNow);command.RequireRecorded(saved);Assert.Equal(InspectionRules.RequirementRevision(f.Pending),command.OriginalInspection.RequirementRevision);Assert.Contains("RequirementRevision",saved.DOCUMENT_ACCEPTANCE_DATA_JSON!);
        var observedRows=source.Inspections.Select(row=>row.InspectionId==saved.INSPECTION_ID?InspectionRules.ProjectWithRequirementProof(saved):row).ToArray();var observed=source with{Inspections=observedRows,SnapshotRevision=CompanyMaintenanceInspectionReview.Revision(source.Stage,source.InspectionDatabase,source.Order,observedRows)};command.RequireCurrentCore(observed,saved);if(mode=="creation-audit"){saved.ROW_CREATED_BY="changed original author";Assert.Throws<InvalidOperationException>(()=>InspectionRules.ProjectForRequirement(saved,command.OriginalInspection));}
    }
    [Theory][InlineData("accepted")][InlineData("text")][InlineData("jurisdiction")][InlineData("creator")][InlineData("creation-time")][InlineData("guid")][InlineData("kind")][InlineData("missing-audit")][InlineData("unknown-timezone")]
    public void NativeRequirementProofPreservesAcceptanceAndDetectsImmutableAuditChanges(string mode)
    {
        var f=Acceptance();var original=InspectionRules.RequirementRevision(f.Pending);var row=f.Command.Prepare(f.Pending,DateTime.UtcNow);Assert.Equal(original,InspectionRules.RequirementRevision(row));Assert.Equal(original,InspectionRules.ProjectWithRequirementProof(row).RequirementRevision);var proofProjection=InspectionRules.ProjectWithRequirementProof(row);InspectionRules.RequireProjected(row.FIELD_ID,row.WORK_ORDER_ID,[proofProjection]);Assert.Throws<InvalidOperationException>(()=>InspectionRules.RequireProjected(row.FIELD_ID,row.WORK_ORDER_ID,[proofProjection with{RequirementRevision="forged"}]));Assert.Null(InspectionRules.Project(row).RequirementRevision);Assert.DoesNotContain("RequirementRevision",JsonSerializer.Serialize(InspectionRules.Project(row)));
        switch(mode){case "text":row.REQUIRED_TEXT="Changed requirement";break;case "jurisdiction":row.JURISDICTION="Changed jurisdiction";break;case "creator":row.ROW_CREATED_BY="another creator";break;case "creation-time":row.ROW_CREATED_DATE=row.ROW_CREATED_DATE!.Value.AddTicks(1);break;case "guid":row.PPDM_GUID=Guid.NewGuid().ToString();break;case "kind":row.PERMIT_PREREQUISITE_KIND="RISK";break;case "missing-audit":row.ROW_CREATED_DATE=null;break;case "unknown-timezone":row.EFFECTIVE_DATE=DateTime.SpecifyKind(DateTime.UtcNow,DateTimeKind.Unspecified);break;}
        if(mode is "missing-audit" or "unknown-timezone")Assert.Throws<InvalidOperationException>(()=>InspectionRules.RequirementRevision(row));else if(mode=="accepted")Assert.Equal(original,InspectionRules.RequirementRevision(row));else Assert.NotEqual(original,InspectionRules.RequirementRevision(row));
    }
    [Fact]
    public async Task HistoricalDocumentAcceptanceIsRecoveryOnlyBeforeTransportOrIntentRetention()
    {
        var f=Acceptance(true);var context=f.Command.Review.PermitReview.Context;var saved=f.Command.Prepare(f.Pending,DateTime.UtcNow);var body=saved.DOCUMENT_ACCEPTANCE_DATA_JSON;var digest=saved.DOCUMENT_ACCEPTANCE_REVISION;
        Assert.DoesNotContain("ContributorReview",body!);Assert.DoesNotContain("ContributorProof",JsonSerializer.Serialize(f.Command.Facts(saved)));Assert.DoesNotContain("ContributorEvidenceVersion",JsonSerializer.Serialize(f.Command.Facts(saved)));f.Command.RequireRecorded(saved);Assert.Equal(body,saved.DOCUMENT_ACCEPTANCE_DATA_JSON);Assert.Equal(digest,saved.DOCUMENT_ACCEPTANCE_REVISION);
        using var company=new CompanyClientContext();Assert.True(company.TrySelect(company.Clear(),context.ActorUserId,new(context.Company,["ConfiguredRole"],["HSE.ApprovePermit"])));
        var transport=new AcceptanceTransport(f.Command,f.Pending,"recovery",()=>company.Clear());using var http=new HttpClient(transport){BaseAddress=new("https://documents.test/")};var client=new BusinessProcessServiceClient(new ApiClient(http,Mock.Of<IFailureReporter>(),company),NullLogger<BusinessProcessServiceClient>.Instance);
        await Assert.ThrowsAsync<InvalidOperationException>(()=>client.RecordWorkOrderDocumentAcceptanceAsync(f.Command));Assert.Equal(0,transport.Calls);
        f.Command.RequireRecorded(await client.RecoverWorkOrderDocumentAcceptanceAsync(f.Command));Assert.Equal(1,transport.Calls);
        using var state=new WorkOrderExecutionPermitDecisionState(company);state.Attach(f.Command.Review.Source.Query.Permit,"source");var retained=false;
        await Assert.ThrowsAsync<InvalidOperationException>(()=>state.AcceptDocumentAsync(client,f.Command.Review,f.Command.InspectionId,f.Command.Reason,true,true,_=>{retained=true;return Task.CompletedTask;}));Assert.False(retained);Assert.Null(state.VisibleDocumentAcceptanceReference);Assert.Equal(1,transport.Calls);
    }
